# Supported key sizes (powers of two)
KEY_SIZE = (16, 32, 64, 128)


# Prefix for generated executables
FILE_PREF = './efildr-'



# C integer type sizes (in bytes)

C_INT8  = 1
C_INT16 = 2
C_INT32 = 4
C_INT64 = 8


# Python field representation types

C_PYTYPE_PTR  = 1 # memoryview
C_PYTYPE_BYTE = 2 # bytes
C_PYTYPE_INT  = 3 # int



# Centralized informational message strings

INF_START = 'Start processing  -> {name}\n'
INF_COMP  = '[*] compressed    :  {org} -> {cmp} bytes  |  saved: {sav} bytes ({prc}%)'
INF_OUT   = '[+] output file   :  {name} ({sz} bytes)'
INF_TIME  = '[*] elapsed time  :  {sec}s'
INF_END   = '\nEnd of processing -> {name}'


# Centralized error message string constants

ERR_PROC  = '\nFailed to process -> {name}'
ERR_IMAGE = '[-] Invalid x86_64 EFI PE32+ image'
ERR_BUILD = '[-] Failed to build output file'



# Exit status codes

EXIT_SUCCESS = 0
EXIT_FAILURE = 1



# RLE constants

RLE_MIN_RUN = 3   # Minimum run length for compression
RLE_MAX_RUN = 127 # Maximum encoded run length
RLE_LIT_MAX = 126 # Maximum literal block length
RLE_FLG_RUN = 128 # High-bit marker for run blocks


# Worst-case compressed buffer size
RLE_BUF_SIZE = lambda sz: (
    (((sz + (RLE_LIT_MAX - 1)) // RLE_LIT_MAX)
    * RLE_MAX_RUN) + RLE_MIN_RUN
)



# STRUCTURES & CONSTANTS EFI PE32+

EFI_FILE_MIN_SIZE = 512     # 512 B
EFI_FILE_MAX_SIZE = 8 << 20 # 8 MiB

IMAGE_DOS_SIGNATURE             = b'MZ'
IMAGE_NT_SIGNATURE              = b'PE\0\0'
IMAGE_NT_OPTIONAL_HDR64_MAGIC   = 0x20B
IMAGE_FILE_MACHINE_X64          = 0x8664
IMAGE_SUBSYSTEM_EFI_APPLICATION = 10


IMAGE_DOS_HEADER = [
    (C_INT16, 'e_magic',  C_PYTYPE_PTR),
    (58,      '__pad',    C_PYTYPE_PTR),
    (C_INT32, 'e_lfanew', C_PYTYPE_INT),
]

IMAGE_FILE_HEADER = [
    (C_INT32, 'Signature', C_PYTYPE_PTR), # from IMAGE_NT_HEADERS64
    (C_INT16, 'Machine',   C_PYTYPE_INT),
    (18,      '__pad',     C_PYTYPE_PTR),
]
IMAGE_FILE_HEADER_SIZE = sum(field[0] for field in IMAGE_FILE_HEADER)

IMAGE_OPTIONAL_HEADER64 = [
    (C_INT16, 'Magic',     C_PYTYPE_INT),
    (66,      '__pad',     C_PYTYPE_PTR),
    (C_INT16, 'Subsystem', C_PYTYPE_INT),
]
IMAGE_OPTIONAL_HEADER64_SIZE = sum(field[0] for field in IMAGE_OPTIONAL_HEADER64)




# Maps a raw binary buffer into named C structure fields,
# According to the specified C layout and Python types
def FillInCStructure(data, struct):
    if (isinstance(data, memoryview)):
        ptr = data
    else:
        ptr = memoryview(data)

    cst = {}
    idx = 0


    for size, name, ptyp in struct:
        val = ptr[idx : idx + size]

        if (ptyp == C_PYTYPE_BYTE):
            val = val.tobytes()

        elif (ptyp == C_PYTYPE_INT):
            val = int.from_bytes(val, 'little')

        cst[name] = val
        idx += size


    return cst




def RleCompress(dat, out):
    datSz = len(dat) # Input boundary
    i = j = 0        # Read and write indices

    while (i < datSz):
        c = dat[i] # Current byte
        r = 1      # Run length

        # Limit the maximum run length
        u = min(RLE_MAX_RUN, datSz - i)
        # Count matching bytes
        while ((r < u) and (dat[i + r] == c)): r += 1


        if (r >= RLE_MIN_RUN):
            out[j]     = r | RLE_FLG_RUN # Write run header
            out[j + 1] = c               # Write repeated byte

            j += 2
            i += r
        else:
            s = i                           # Literal block start
            u = min(RLE_LIT_MAX + s, datSz) # Limit the literal block length

            # Scan until the next run
            while ((i < u) and not (
                ((i + (RLE_MIN_RUN - 1)) < datSz) and
            # Check for a RLE_MIN_RUN-byte run
                (dat[i] == dat[i + 1] == dat[i + 2])
            )): i += 1


            l = i - s # Literal length

            if (l):
                out[j] = l # Write literal length
                j += 1

                out[j : j + l] = dat[s : i] # Copy literal bytes
                j += l


    return out[:j] # Trim output to actual written size




def ArxEncrypt(dat, key):
    msk = len(key) - 1 # Power-of-two key mask
    stt = key[0]       # Rolling cipher state

    end = len(dat) # Input boundary
    i = idx = 0    # Stream position counter


    while (i < end):
        p = dat[i] # Input byte
        j = idx
        s = stt

        k1 = key[(j * 7 ) & msk]
        k2 = key[(j * 13) & msk]
        k3 = key[(j * 23) & msk]


        # Invert step 5: _r = (~_r ^ _k3) + (_k1 ^ (_k2 & ~_s))
        t  = (p - (k1 ^ (k2 & ~s))) & 0xFF
        t  = (t ^ k3) & 0xFF
        r4 = (~t) & 0xFF

        # Invert step 4: _r = ((_r << 3) | (_r >> 5)) - (_s << 1)
        t  = (r4 + (s << 1)) & 0xFF
        r3 = ((t >> 3) | (t << 5)) & 0xFF

        # Invert step 3: _r = _r ^ ((_s >> 3) - _k2)
        r2 = (r3 ^ ((s >> 3) - k2)) & 0xFF

        # Invert step 2: _r = ((_r << 6) | (_r >> 2)) + _k1
        t  = (r2 - k1) & 0xFF
        r1 = ((t >> 6) | (t << 2)) & 0xFF

        # Invert step 1: _r = (~(b) ^ _s) + _k3
        t = (r1 - k3) & 0xFF
        t = (t ^ s) & 0xFF
        b = (~t) & 0xFF


        dat[i] = b # Write ciphertext byte

        stt = (((s >> (p & 7)) ^ k2)
            +  ((p << (s & 7)) ^ k1)
            -  ((k3 * j) | 1)) & 0xFF

        i   += 1
        idx += 1


    return None




def ReadFile(fpath):
    try:
        with open(fpath, 'rb') as f:
            data = memoryview(f.read())

            return (data, len(data))
    except OSError:
        return (None, 0)




def ValidEfiFile(data, dataSz):
    if (not (EFI_FILE_MIN_SIZE <= dataSz <= EFI_FILE_MAX_SIZE)):
        return False


    hdDos    = FillInCStructure(data, IMAGE_DOS_HEADER)
    e_lfanew = hdDos['e_lfanew']

    if ((hdDos['e_magic'] != IMAGE_DOS_SIGNATURE) or
        (dataSz < (e_lfanew +
                   (IMAGE_FILE_HEADER_SIZE +
                    IMAGE_OPTIONAL_HEADER64_SIZE)))
    ): return False


    hdFile = FillInCStructure(data[e_lfanew:], IMAGE_FILE_HEADER)

    if ((hdFile['Signature'] != IMAGE_NT_SIGNATURE    ) or
        (hdFile['Machine']   != IMAGE_FILE_MACHINE_X64)
    ): return False


    hdOptl = FillInCStructure(
        data[e_lfanew + IMAGE_FILE_HEADER_SIZE:],
        IMAGE_OPTIONAL_HEADER64
    )

    if ((hdOptl['Magic']     != IMAGE_NT_OPTIONAL_HDR64_MAGIC  ) or
        (hdOptl['Subsystem'] != IMAGE_SUBSYSTEM_EFI_APPLICATION)
    ): return False


    return True




# Overlay layout (in file order)
#   1. loader_stub : EFI_PE_STUB
#   2. key_size    : DAT_KEY_SZ
#   3. key         : PE_KEY
#   4. raw_len     : DAT_LEN_SZ
#   5. payload     : PE_EXE
#   6. total_len   : DAT_LEN_SZ (at the end, read by ReadOverLay)
#
def BuildEfiFile(
    file, fSz,
    out,  outSz,
    key,  kLn
):
    stub = bytearray(EFI_PE_STUB)

    stub.append(kLn)
    stub.extend(key)

    stub.extend(fSz.to_bytes(C_INT32, 'little'))
    stub.extend(out)

    tlLn = (C_INT8 + kLn) + (C_INT32 + outSz)
    stub.extend(tlLn.to_bytes(C_INT32, 'little'))


    try:
        with open(file, 'wb') as f:
            f.write(stub)

        return len(stub)
    except OSError:
        return 0




# Processes the target EFI image
# and builds the output loader
def Setup(fpath):
    timestamp = time.time()
    print(INF_START.format(name=fpath))


    outFileName        = FILE_PREF + os.path.basename(fpath)
    fileData, fileSize = ReadFile(fpath)

    if (not (fileSize and ValidEfiFile(fileData, fileSize))):
        print(ERR_IMAGE)
        return False


    kLn = KEY_SIZE[int(timestamp) % len(KEY_SIZE)]
    key = os.urandom(kLn)

    out = bytearray(RLE_BUF_SIZE(fileSize))
    ptr = memoryview(out)


    ptr = RleCompress(fileData, ptr)
    del fileData

    ArxEncrypt(ptr, key)
    outSz = len(ptr)

    print(INF_COMP.format(
        org=fileSize, cmp=outSz,
        sav=fileSize - outSz,
        prc=round(((fileSize - outSz) * 100) / fileSize, 1)
    ))


    outFileSize = BuildEfiFile(
        outFileName, fileSize,
        ptr,         outSz,
        key,         kLn
    )
    if (not outFileSize):
        print(ERR_BUILD)
        return False

    print(INF_OUT.format(name=outFileName,
                           sz=outFileSize))


    elapsed = time.time() - timestamp
    print(INF_TIME.format(sec=round(elapsed, 2)))


    print(INF_END.format(name=fpath))
    return True




def main(argc, argv):
    if (argc < 2):
        print(
            '\n(C) Vladislav Khudash, 2026'
            '\n(P) GitHub: https://github.com/vk-candpython/efildr'
            '\n(!) Only for x86_64 EFI (PE32+)\n'

            '\n\n(Usage):\n'
                '  python efildr.py <efi> [efi ...]\n'

            '\n\n(Features):\n'
                '  - RLE compression\n'
                '  - ARX stream cipher\n'
                '  - Fileless execution\n'
                '  - More features on GitHub\n'
        )
        return EXIT_FAILURE


    print()
    sep = False

    for fpath in argv[1:]:
        if (sep): print('\n')
        sep = True

        if (not Setup(fpath)):
            print(ERR_PROC.format(name=fpath))


    print()
    return EXIT_SUCCESS




if (__name__ == '__main__'):
    status = main(len(sys.argv), sys.argv)
    sys.exit(status)
